import React from 'react';
import { render } from '@testing-library/react-native';
import { AddGreetCommandScreen } from '../screens/AddGreetCommandScreen';

describe('AddGreetCommandScreen', () => {
  it('renders the AddGreetCommand title', async () => {
    const { getByText } = await render(<AddGreetCommandScreen />);
    expect(getByText('AddGreetCommand')).toBeDefined();
  });
});

// TDD test suite for useAddGreetCommand — written before implementation.

import { renderHook, act } from '@testing-library/react-native';
import { useAddGreetCommand } from '../hooks/useAddGreetCommand';

describe('useAddGreetCommand', () => {
  it('starts in the default state', async () => {
    const { result } = await renderHook(() => useAddGreetCommand());
    expect(result.current.loading).toBe(false);
    expect(result.current.error).toBeNull();
    expect(result.current.data).toBeNull();
  });

  it('stores the result after running', async () => {
    const { result } = await renderHook(() => useAddGreetCommand());
    await act(async () => {
      await result.current.run();
    });
    expect(result.current.data).toBe('ok');
    expect(result.current.loading).toBe(false);
  });
});

// TDD test suite for AddGreetCommandApi — written before implementation.

import { addGreetCommandApi } from '../services/AddGreetCommandApi';

describe('AddGreetCommandApi', () => {
  it('executes and returns a result', async () => {
    const result = await addGreetCommandApi.execute();
    expect(result).toBeDefined();
  });
});

